arguments.command:
cd /app/data; python3 - <<'E'
import glob,gzip,collections
for f in sorted(glob.glob('*')):
    b=open(f,'rb').read()
    tags=[]
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b); tags.append('gz')
    if b[:3]==b'\xef\xbb\xbf': tags.append('bom8')
    if b[:2] in (b'\xff\xfe',b'\xfe\xff'): tags.append('bom16')
    if b'charset' in b[:500]: tags.append(b[:500].split(b'charset')[1][:20])
    if b'\r' in b: tags.append('CR')
    if tags: print(f,tags)
