arguments.command:
cd /app/data; python3 - <<'E'
import glob,gzip,csv,io,collections,re,json
def rd(f):
    b=open(f,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    return b
# field-count anomalies for delimited
for f in sorted(glob.glob('east*')+glob.glob('lakeside*')+glob.glob('west*')+glob.glob('river*')+glob.glob('harbor*')):
    b=rd(f)
    if b[:3]==b'\xef\xbb\xbf': t=b[3:].decode()
    elif b[:2] in(b'\xff\xfe',b'\xfe\xff'): t=b.decode('utf-16')
    elif b'windows-1252' in b[:200]: t=b.decode('cp1252')
    else: t=b.decode()
    d={'e':',','l':',','w':';','r':'\t','h':'|'}[f[0]]
    hdr=None;c=collections.Counter()
    for row in csv.reader(io.StringIO(t,newline=''),delimiter=d) if d==',' else (l.split(d) for l in t.split('\n')):
        if not row or row[0].startswith('#'): continue
        if hdr is None or row[0] in('id','t','rec','type','shipped','note','status') and 'status' in row and len(row)==len(hdr) and all(x.isalpha() or '_' in x for x in row):
            hdr=row;continue
        if len(row)!=len(hdr): c[(len(row),len(hdr))]+=1; 
        if len(row)!=len(hdr) and c[(len(row),len(hdr))]<3: print(f,row)
    if c: print(f,dict(c))
E

