#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import calendar
import datetime as dt
import gzip
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from decimal import Decimal, ROUND_HALF_UP, getcontext

getcontext().prec = 60

UNIT_KG = {
    "kg": Decimal("1"),
    "g": Decimal("0.001"),
    "lb": Decimal("0.45359237"),
    "oz": Decimal("0.028349523125"),
}
PRIORITY = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
MONTHS = {m.lower(): i for i, m in enumerate(calendar.month_abbr) if m}
MONTHS.update({m.lower(): i for i, m in enumerate(calendar.month_name) if m})

COLUMNS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
}
DELIM = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
# canonical field names per depot
CANON = {
    "east": {"id": "id", "type": "type", "shipped": "shipped", "gross": "weight", "status": "status"},
    "harbor": {"rec": "type", "ref": "id", "date": "shipped", "weight": "weight", "state": "status"},
    "lakeside": {"id": "id", "kind": "type", "shipped": "shipped", "gross_kg": "weight", "status": "status"},
    "river": {"t": "type", "ref": "id", "shipped": "shipped", "weight": "weight", "status": "status"},
    "west": {"id": "id", "typ": "type", "shipped": "shipped", "weight": "weight", "status": "status"},
}
BASE_DATE = {"east": "ymd", "harbor": "iso", "lakeside": "iso", "river": "mm/dd/yyyy", "west": "dd.mm.yyyy"}
FIXED_UNIT = {"lakeside": "kg"}  # unit named by the weight field

FW = {
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26),
                date="yyyyddd", scale=Decimal("1"), unit="g"),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27),
                date="yyyymmdd", scale=Decimal("0.01"), unit="kg"),
    "FW3": dict(length=41, id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25),
                date="yyyyddd", scale=Decimal("0.1"), unit="lb"),
}
FW_STATUS = {"D": "delivered", "L": "delivered_late", "C": "cancelled", "R": "returned", "H": "held"}
HARBOR_STATUS = {"DLV": "delivered", "DLL": "delivered_late", "CAN": "cancelled", "RET": "returned",
                 "HLD": "held"}


# ---------------------------------------------------------------- helpers
def read_bytes(path):
    b = open(path, "rb").read()
    if b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8")
    if b[:2] == b"\xff\xfe":
        return b[2:].decode("utf-16-le")
    if b[:2] == b"\xfe\xff":
        return b[2:].decode("utf-16-be")
    m = re.search(rb"^#[ \t]*charset[ \t]*:[ \t]*([A-Za-z0-9_.:-]+)", b[:4096], re.M | re.I)
    if m:
        try:
            return b.decode(m.group(1).decode("ascii"))
        except (LookupError, UnicodeDecodeError):
            pass
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        return b.decode("cp1252", errors="replace")


def norm_id(s):
    m = re.fullmatch(r"\s*SH\D*?(\d+)\s*", s or "", re.I)
    return int(m.group(1)) if m else None


def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def rtype(s):
    s = (s or "").strip().lower()
    if s[:1] in ("c", "a"):
        return "C"
    if s[:1] == "v":
        return "V"
    return "N"


def parse_weight(text, unit, decimal_comma=False):
    """Return Decimal kilograms or None. A unit written with the value wins."""
    t = (text or "").strip()
    m = re.fullmatch(r"([-+0-9.,\s]*?)\s*([A-Za-z]*)", t)
    if not m or not m.group(1).strip():
        return None
    num, u = m.group(1).replace(" ", ""), m.group(2).lower()
    if u:
        unit = u
    if decimal_comma:
        num = num.replace(".", "").replace(",", ".")
    else:
        num = num.replace(",", "")
    try:
        return Decimal(num) * UNIT_KG[unit]
    except (KeyError, ArithmeticError):
        return None


def parse_date(text, form):
    """Return (year, month) for a date string in the given form."""
    t = (text or "").strip()
    form = (form or "iso").strip().lower()
    if form == "serial" or re.fullmatch(r"\d{4,6}", t) and form not in ("yyyyddd", "yyyymmdd"):
        d = dt.date(1899, 12, 30) + dt.timedelta(days=int(float(t)))
        return d.year, d.month
    if form == "yyyyddd":
        d = dt.date(int(t[:4]), 1, 1) + dt.timedelta(days=int(t[4:7]) - 1)
        return d.year, d.month
    if form == "yyyymmdd":
        return int(t[:4]), int(t[4:6])
    m = re.fullmatch(r"(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})", t)
    if m:
        return int(m.group(3)), MONTHS[m.group(2).lower()]
    p = [int(x) for x in re.split(r"[-/.]", t)[:3]]
    if form in ("iso", "ymd", "yyyy-mm-dd"):
        return p[0], p[1]
    if form in ("dmy", "dd/mm/yyyy", "dd.mm.yyyy", "dd-mm-yyyy"):
        return p[2], p[1]
    if form in ("mm/dd/yyyy", "mdy", "mm-dd-yyyy"):
        return p[2], p[0]
    raise ValueError("unknown date form " + form)


def parse_time(text, form="iso"):
    """Ship time -> (year, month) in UTC. Date-only values are UTC dates."""
    t = (text or "").strip()
    if re.match(r"\d{4}-\d{2}-\d{2}[T ]\d", t):
        d = dt.datetime.fromisoformat(t)
        if d.tzinfo is not None:
            d = d.astimezone(dt.timezone.utc)
        return d.year, d.month
    return parse_date(t, form)


def mk(num, typ, ym, kg, status):
    return dict(num=num, type=typ, ym=ym, kg=kg, status=status)


# ---------------------------------------------------------------- delimited
def split_records(text, quoting):
    """Yield ('comment', line) or ('row', raw_record_text) honouring quoted newlines."""
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i].rstrip("\r")
        i += 1
        if line.startswith("#"):
            yield "comment", line
            continue
        if not line.strip():
            continue
        rec = line
        if quoting:
            while rec.count('"') % 2 == 1 and i < len(lines):
                rec += "\n" + lines[i].rstrip("\r")
                i += 1
        yield "row", rec


def split_fields(rec, delim, quoting):
    if not quoting:
        return rec.split(delim)
    out, cur, inq, i = [], [], False, 0
    while i < len(rec):
        c = rec[i]
        if inq:
            if c == '"':
                if rec[i + 1:i + 2] == '"':
                    cur.append('"')
                    i += 1
                else:
                    inq = False
            else:
                cur.append(c)
        elif c == '"':
            inq = True
        elif c == delim:
            out.append("".join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    out.append("".join(cur))
    return out


def parse_delimited(depot, text):
    cols = COLUMNS[depot]
    colset = set(cols)
    delim = DELIM[depot]
    quoting = delim == ","
    canon = CANON[depot]
    seq = None
    d = {"date": BASE_DATE[depot], "unit": None}
    hdr = None
    recs = []
    for kind, raw in split_records(text, quoting):
        if kind == "comment":
            m = re.match(r"#\s*([^:=]+?)\s*:\s*(.*?)\s*$", raw)
            if m:
                name, val = m.group(1).lower(), m.group(2)
                if name == "seq":
                    if seq is None and re.match(r"\d+", val):
                        seq = int(re.match(r"\d+", val).group())
                elif name in ("dates", "date format", "date", "date form"):
                    d["date"] = val.split()[0] if val else d["date"]
                elif name in ("unit", "weight unit"):
                    d["unit"] = val.split()[0].lower() if val else None
                    d["comma"] = "decimal comma" in val.lower()
            else:
                m = re.search(r"\bseq=(\d+)", raw)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        row = split_fields(raw, delim, quoting)
        low = [f.strip().lower() for f in row]
        if all(f in colset for f in low):
            hdr = low
            continue
        if hdr is None:
            hdr = list(cols)
        rowunit = None
        if len(row) == len(hdr) + 1:
            wcol = next((j for j, h in enumerate(hdr) if canon.get(h) == "weight"), None)
            if wcol is not None:
                rowunit = row[wcol + 1].strip().lower()
                row = row[:wcol + 1] + row[wcol + 2:]
        if len(row) < len(hdr):
            row = row + [""] * (len(hdr) - len(row))
        f = {canon[h]: row[j] for j, h in enumerate(hdr) if h in canon}
        num = norm_id(f.get("id"))
        if num is None:
            continue
        typ = rtype(f.get("type"))
        if typ == "V":
            recs.append(mk(num, "V", None, None, None))
            continue
        unit = rowunit or d["unit"] or FIXED_UNIT.get(depot) or "kg"
        if depot == "lakeside":
            unit = "kg"
        comma = depot == "west" or d.get("comma", False)
        kg = parse_weight(f.get("weight"), unit, comma)
        ym = parse_time(f.get("shipped"), d["date"])
        st = f.get("status", "")
        if depot == "harbor":
            st = HARBOR_STATUS.get(st.strip().upper(), st)
        recs.append(mk(num, typ, ym, kg, norm_status(st)))
    return seq, recs


# ---------------------------------------------------------------- fixed width
def parse_fixed(text):
    seq = None
    layout = None
    recs = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if "\f" in line or "SHIPMENT LISTING" in line:
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\w+)", line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if not line.strip():
            continue
        lay = layout if layout in FW and len(line) == FW[layout]["length"] else None
        if lay is None:
            lay = next((k for k, v in FW.items() if v["length"] == len(line)), None)
        if lay is None and layout in FW and len(line) < FW[layout]["length"]:
            lay = layout
            line = line.ljust(FW[layout]["length"])
        if lay is None:
            continue
        spec = FW[lay]
        g = lambda k: line[spec[k][0]:spec[k][1]]
        num = norm_id(g("id"))
        if num is None:
            continue
        typ = rtype(g("type"))
        if typ == "V":
            recs.append(mk(num, "V", None, None, None))
            continue
        kg = Decimal(int(g("weight"))) * spec["scale"] * UNIT_KG[spec["unit"]]
        ym = parse_date(g("shipped"), spec["date"])
        recs.append(mk(num, typ, ym, kg, FW_STATUS.get(g("status").strip().upper(), "")))
    return seq, recs


# ---------------------------------------------------------------- XML
def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get("seq")) if (root.get("seq") or "").strip().isdigit() else None
    base = (root.get("weight-unit") or root.get("unit") or "kg").lower()
    recs = []
    for el in root.iter("shipment"):
        num = norm_id(el.get("id"))
        if num is None:
            continue
        typ = rtype(el.get("type"))
        if typ == "V":
            recs.append(mk(num, "V", None, None, None))
            continue
        w = el.find("weight")
        if w is not None:
            wt, unit = w.text, (w.get("unit") or base).lower()
        else:
            wt, unit = el.get("weight"), (el.get("unit") or base).lower()
        sh = el.find("shipped")
        stext = sh.text if sh is not None else el.get("shipped")
        st = el.find("status")
        recs.append(mk(num, typ, parse_time(stext, "iso"), parse_weight(wt, unit),
                       norm_status(st.text if st is not None else el.get("status"))))
    return seq, recs


# ---------------------------------------------------------------- JSON lines
def parse_jsonl(text):
    seq = None
    recs = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        v = json.loads(line)
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict):
                if seq is None and o["meta"].get("seq") is not None:
                    seq = int(o["meta"]["seq"])
                continue
            num = norm_id(str(o.get("id", "")))
            if num is None:
                continue
            typ = rtype(o.get("kind"))
            if typ == "V":
                recs.append(mk(num, "V", None, None, None))
                continue
            kg = None
            for k, val in o.items():
                m = re.fullmatch(r"weight(?:_(\w+))?", k)
                if m:
                    unit = (m.group(1) or o.get("unit") or "kg").lower()
                    kg = parse_weight(str(val), unit)
            recs.append(mk(num, typ, parse_time(o.get("shipped_at"), "iso"), kg,
                           norm_status(o.get("status"))))
    return seq, recs


def parse_file(depot, path):
    b = read_bytes(path)
    if depot == "central" or b.lstrip()[:5] == b"<?xml" or b.lstrip()[:1] == b"<":
        return parse_xml(b)
    text = decode(b)
    if depot == "north" or text.lstrip()[:1] in "{[":
        return parse_jsonl(text)
    if depot == "south":
        return parse_fixed(text)
    return parse_delimited(depot, text)


# ---------------------------------------------------------------- main
def q2(x):
    return float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    files = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.setdefault(name.split("-", 1)[0].lower(), []).append(p)
    corrections = resends = 0
    current = {}
    for depot, paths in files.items():
        exports = []
        for p in paths:
            seq, recs = parse_file(depot, p)
            exports.append((seq if seq is not None else -1, os.path.basename(p), recs))
        exports.sort(key=lambda e: (e[0], e[1]))
        cur = {}
        for _, _, recs in exports:
            for r in recs:
                n = r["num"]
                if r["type"] == "N":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "C":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    order = {d: i for i, d in enumerate(PRIORITY)}
    ranked = sorted(current, key=lambda d: (order.get(d, len(order)), d))
    kept, owners = {}, {}
    for depot in ranked:
        for n, r in current[depot].items():
            owners[n] = owners.get(n, 0) + 1
            if n not in kept:
                kept[n] = (depot, r)
    handovers = sum(1 for c in owners.values() if c > 1)

    depots = {d: [0, Decimal(0)] for d in sorted(files)}
    months = {}
    for depot, r in kept.values():
        if r["status"] not in ("delivered", "delivered_late") or r["kg"] is None or r["ym"] is None:
            continue
        depots[depot][0] += 1
        depots[depot][1] += r["kg"]
        key = "%04d-%02d" % r["ym"]
        m = months.setdefault(key, [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]
    out = {
        "depots": {d: {"shipments": v[0], "total_kg": q2(v[1])} for d, v in depots.items()},
        "months": {k: {"shipments": months[k][0], "total_kg": q2(months[k][1])} for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
